unsigned short PORT_BASE = 0x3F0;
unsigned short status_word;

// --- Permission Grant (Required) ---
// Grants access to 8 ports starting at PORT_BASE
// Requires iopl(3) or root/CAP_SYS_RAWIO
ioperm(PORT_BASE, 8, 1);

// --- 16-bit Input Read ---
status_word = inw(PORT_BASE);

// --- 16-bit Input with short delay/polling ---
status_word = inw_p(PORT_BASE + 2);

// --- Revoke Permission ---
ioperm(PORT_BASE, 8, 0);
